form.script:
                (function () {
                var canvas = document.getElementById('v-sig-canvas');
                if (!canvas || !canvas.getContext) { return; }
                var hidden = document.querySelector('input[name="signature_data"]');
                var ctx = canvas.getContext('2d');
                var drawing = false;
var strokes = [];
var touched = false;
var hiddenSvg = document.querySelector('input[name="signature_paths"]');
                function fill() { ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, canvas.width, canvas.height); }
                function trimmed() {
var w = canvas.width; var h = canvas.height;
var data = ctx.getImageData(0, 0, w, h).data;
var minX = w; var minY = h; var maxX = -1; var maxY = -1;
for (var y = 0; y < h; y++) {
for (var x = 0; x < w; x++) {
var i = (y * w + x) * 4;
if (data[i] < 245 || data[i + 1] < 245 || data[i + 2] < 245) {
if (x < minX) { minX = x; }
if (x > maxX) { maxX = x; }
if (y < minY) { minY = y; }
if (y > maxY) { maxY = y; }
}
}
}
if (maxX < 0) { return canvas; }
var pad = 8;
minX = Math.max(0, minX - pad); minY = Math.max(0, minY - pad);
maxX = Math.min(w - 1, maxX + pad); maxY = Math.min(h - 1, maxY + pad);
var out = document.createElement('canvas');
out.width = maxX - minX + 1; out.height = maxY - minY + 1;
out.getContext('2d').drawImage(canvas, minX, minY, out.width, out.height, 0, 0, out.width, out.height);
return out;
}
function boxed() {
/* The PDF engine collapses images sized with width:auto inside table
   cells, so the signature is normalised into a fixed 4:1 box and the
   report styles that box explicitly. The drawing itself is untouched. */
var cut = trimmed();
var fixed = document.createElement('canvas');
fixed.width = 640; fixed.height = 160;
var fc = fixed.getContext('2d');
fc.fillStyle = '#ffffff';
fc.fillRect(0, 0, 640, 160);
var scale = Math.min(1, (640 - 24) / cut.width, (160 - 16) / cut.height);
var dw = cut.width * scale;
var dh = cut.height * scale;
fc.drawImage(cut, (640 - dw) / 2, (160 - dh) / 2, dw, dh);
return fixed;
}
function pathData() {
var d = '';
for (var s = 0; s < strokes.length; s++) {
var pts = strokes[s];
for (var i = 0; i < pts.length; i++) {
d += (i === 0 ? 'M' : ' L') + Math.round(pts[i].x) + ' ' + Math.round(pts[i].y) + ' ';
}
}
return d;
}
function sync() {
if (!touched) { return; }
if (hidden) { hidden.value = boxed().toDataURL('image/png'); }
if (hiddenSvg && strokes.length) { hiddenSvg.value = pathData(); }
}
                function pos(ev) {
                var r = canvas.getBoundingClientRect();
                var src = (ev.touches && ev.touches.length) ? ev.touches[0] : ev;
                return {x: (src.clientX - r.left) * (canvas.width / r.width),
                y: (src.clientY - r.top) * (canvas.height / r.height)};
                }
                function start(ev) {
                touched = true;
drawing = true; var p = pos(ev); strokes.push([p]); ctx.beginPath(); ctx.moveTo(p.x, p.y);
                if (ev.cancelable) { ev.preventDefault(); }
                }
                function move(ev) {
                if (!drawing) { return; }
                var p = pos(ev);
var seg = strokes[strokes.length - 1];
var last = seg[seg.length - 1];
if (Math.abs(p.x - last.x) + Math.abs(p.y - last.y) < 2) { return; }
seg.push(p);
ctx.lineTo(p.x, p.y); ctx.stroke();
                if (ev.cancelable) { ev.preventDefault(); }
                }
                function end() { if (!drawing) { return; } drawing = false; ctx.closePath(); sync(); }
                fill();
                ctx.lineWidth = 2.2; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
                ctx.strokeStyle = '#0B1220';
                var existing = canvas.getAttribute('data-existing');
                if (existing) {
                var img = new Image();
                img.onload = function () {
                var scale = Math.min(1, (canvas.width - 24) / img.width, (canvas.height - 24) / img.height);
                var w = img.width * scale; var h = img.height * scale;
                ctx.drawImage(img, (canvas.width - w) / 2, (canvas.height - h) / 2, w, h);
                sync();
                };
                img.src = existing;
                }
                canvas.addEventListener('mousedown', start);
                canvas.addEventListener('mousemove', move);
                window.addEventListener('mouseup', end);
                canvas.addEventListener('touchstart', start, {passive: false});
                canvas.addEventListener('touchmove', move, {passive: false});
                canvas.addEventListener('touchend', end);
                var clear = document.getElementById('v-sig-clear');
                if (clear) {
                clear.addEventListener('click', function (ev) { ev.preventDefault(); drawing = false; strokes = []; touched = false; fill(); sync(); });
                }
                })();

div.script:
(function () {
    var KEY = 'verdicta_tab';
    var bar = document.querySelector('.v-tabbar');
    if (!bar) { return; }

    function select(key, remember) {
        bar.querySelectorAll('.v-tab').forEach(function (b) {
            var on = b.dataset.tab === key;
            b.classList.toggle('active', on);
            b.setAttribute('aria-selected', on ? 'true' : 'false');
        });
        document.querySelectorAll('.v-tabpane').forEach(function (p) {
            p.classList.toggle('active', p.dataset.pane === key);
        });
        if (remember) {
            try { window.sessionStorage.setItem(KEY, key); } catch (e) {}
        }
    }

    bar.addEventListener('click', function (ev) {
        var btn = ev.target.closest('.v-tab');
        if (btn) { select(btn.dataset.tab, true); }
    });

    var first = bar.querySelector('.v-tab');
    var saved = null;
    try { saved = window.sessionStorage.getItem(KEY); } catch (e) {}
    var valid = saved && bar.querySelector('.v-tab[data-tab="' + saved + '"]');
    select(valid ? saved : (first ? first.dataset.tab : null), false);

    // Right/left arrows move between tabs, as expected of a tablist.
    bar.addEventListener('keydown', function (ev) {
        if (ev.key !== 'ArrowRight' && ev.key !== 'ArrowLeft') { return; }
        var tabs = Array.prototype.slice.call(bar.querySelectorAll('.v-tab'));
        var i = tabs.indexOf(document.activeElement);
        if (i < 0) { return; }
        ev.preventDefault();
        var next = tabs[(i + (ev.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length];
        next.focus();
        select(next.dataset.tab, true);
    });
})();
